import dataset from './generated/signatures.json'
import type { DrivingSignature, SignatureEra } from '@/lib/types'

// Generated by backend/pipeline/signature (see SPEC.md there). Do not hand-edit the JSON.
interface SignatureDataset {
  generatedAt: string
  pipelineVersion: string
  source: string
  seasons: number[]
  axes: string[]
  eras: SignatureEra[]
  drivers: Record<string, {
    name: string
    defaultEra: string
    signatures: Record<string, DrivingSignature>
  }>
}

const DATA = dataset as unknown as SignatureDataset

/** Timing-telemetry signature for an F1 driver page slug, in the driver's most recent scored era. */
export function getTimingSignature(slug: string): DrivingSignature | null {
  const entry = DATA.drivers[slug]
  return entry?.signatures[entry.defaultEra] ?? null
}
